/* Spins the moby and animates four 30-point strands: a strand whose timer ran out is rebuilt with a smoothed random drift (each point averages three jitters) and its timer reset; otherwise every inner point moves by its drift.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l06/gameplay/entities/002b4770.c, FUN_L06_002f7000. */
void animate_beam_barrier_strands(struct Moby *moby) {
    Vec4 jitter[30];
    float y;
    float step;
    float phase;
    int i;
    int j;
    int k;

    moby->rot.x = FastAddRots(moby->rot.x, D_L06_00161EA0_F8430 * 0.017453292f * g_frame_time);
    phase = D_L06_00161E8C_F8430 + D_L06_00161E90_F8430 * g_frame_time;
    moby->scale = *(f32 *)((char *)moby->pclass + 0x24) * D_L06_00161EA4_F8430;
    D_L06_00161E8C_F8430 = phase;
    if (phase > 1.0f) {
        D_L06_00161E8C_F8430 = phase - 1.0f;
    }
    step = D_L06_00161E98_F8430 / 30.0f;
    y = -(D_L06_00161E98_F8430 * 0.5f);
    for (i = 0; i < 4; i++) {
        if (beam_barrier_strand_timers[i] == 0) {
            for (k = 0; k < 30; k++) {
                set_vec_to_origin_point(&beam_barrier_strand_points[i][k]);
                beam_barrier_strand_points[i][k].f[1] = y;
                rand_vec_r(&jitter[k], 0.0f, D_L06_00161E94_F8430 * g_frame_time);
                y += step;
            }
            for (k = 1; k < 29; k++) {
                FastVecAdd(&beam_barrier_strand_drift[i][k], &jitter[k - 1], &jitter[k]);
                FastVecAdd(&beam_barrier_strand_drift[i][k], &beam_barrier_strand_drift[i][k], &jitter[k + 1]);
                FastVecScale(&beam_barrier_strand_drift[i][k], &beam_barrier_strand_drift[i][k], 0.333f);
            }
            beam_barrier_strand_timers[i] = beam_barrier_strand_life;
        } else {
            for (j = 1; j < 29; j++) {
                FastVecAdd(&beam_barrier_strand_points[i][j], &beam_barrier_strand_points[i][j], &beam_barrier_strand_drift[i][j]);
            }
            beam_barrier_strand_timers[i]--;
        }
    }
}
