/* Circles its centre point on the side away from the hero (at most 45 degrees per step), faces its focus moby, moves while the hero is within 16 units and snaps to the ground.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l06/gameplay/entities/002b4770.c, FUN_L06_002fbc88. */
void update_alien_queen_orbit_movement(struct Moby *m) {
    CirclerVars *v = (CirclerVars *)m->pvars;
    struct Moby *focus = v->focus;
    Vec4f goal, step;
    f32 hero_ang;
    f32 self_ang;
    f32 d;

    hero_ang = fast_atan2(g_hero.motion.pos.f[0] - v->center.x, g_hero.motion.pos.f[1] - v->center.y);
    self_ang = fast_atan2(m->pos.x - v->center.x, m->pos.y - v->center.y);
    d = FastSubRots(FastAddRots(hero_ang, 3.14159f), self_ang);
    if (d > 0.7853982f)
        d = 0.7853982f;
    else if (d < -0.7853982f)
        d = -0.7853982f;
    d = FastAddRots(d, self_ang);
    goal.x = FastCos(d) * v->radius;
    goal.y = FastSin(d) * v->radius;
    goal.z = 0.0f;
    FastVecAdd(&goal, &goal, &v->center);
    SteerAngleWithVelocity_r2(&m->rot.z, fast_atan2(focus->pos.x - m->pos.x, focus->pos.y - m->pos.y),
                           &v->yaw_vel, g_frame_time_sq * 6.2831855f, g_frame_time_sq * 6.2831855f,
                           g_frame_time * 3.1415927f);
    if (FastVecDist(&m->pos, &goal) > 1.0f && vec_distance_xy(&m->pos, &g_hero.motion.pos) < 16.0f)
        ApproachValue(&v->speed, (*(f32 *)&circler_max_speed) * g_frame_time, (*(f32 *)&alien_queen_walk_accel) * g_frame_time_sq);
    else
        ApproachValue(&v->speed, 0.0f, (*(f32 *)&alien_queen_walk_accel) * g_frame_time_sq);
    if (v->speed == 0.0f) {
        if (m->prev_seq != 1)
            MobyBlendAnimation(m, 1, 0, scale_ticks(20));
    } else if (m->prev_seq != 0) {
        MobyBlendAnimation(m, 0, 0, scale_ticks(20));
    }
    FastVecSub(&step, &goal, &m->pos);
    step.z = 0.0f;
    vec_scale_to_length(&step, &step, v->speed);
    FastVecAdd(&m->pos, &m->pos, &step);
    resolve_point_path_segment_xy_clearance(1.0f, v->ground, &m->pos, &m->pos);
}
